def evaluate(before, during, max_drop_pct, max_p95_ms):
    reasons = []
    if before['success_rate'] - during['success_rate'] > max_drop_pct:
        reasons.append('success_rate')
    if during['p95'] > max_p95_ms:
        reasons.append('p95')
    return (not reasons, reasons)

