coding.solution:
async function withFallback(call, ms, fallback) {
  let timer;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(() => resolve({ source: 'fallback', value: fallback }), ms);
  });
  const live = Promise.resolve()
    .then(call)
    .then((value) => ({ source: 'live', value }))
    .catch(() => ({ source: 'fallback', value: fallback }));
  try {
    return await Promise.race([live, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

